import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';
import '../core/auth/auth_controller.dart';import '../features/auth/login_screen.dart';import '../features/debts/debts_module.dart';import '../features/onboarding/onboarding_screen.dart';import '../features/plan/plan_module.dart';import '../features/profile/profile_screen.dart';import '../features/today/today_screen.dart';import '../features/transactions/transactions_module.dart';import 'main_shell.dart';
final routerProvider=Provider<GoRouter>((ref){final auth=ref.watch(authControllerProvider);return GoRouter(initialLocation:'/welcome',redirect:(_,s){final path=s.matchedLocation;final public=path=='/welcome'||path=='/login';if(auth==SessionState.loading)return path=='/loading'?null:'/loading';if(path=='/loading')return auth==SessionState.anonymous?'/welcome':auth==SessionState.onboarding?'/onboarding':'/today';if(auth==SessionState.anonymous)return public?null:'/welcome';if(auth==SessionState.onboarding)return path=='/onboarding'?null:'/onboarding';if(auth==SessionState.authenticated&&(public||path=='/onboarding'))return'/today';return null;},routes:[GoRoute(path:'/loading',builder:(_,__)=>const Scaffold(body:Center(child:CircularProgressIndicator()))),GoRoute(path:'/welcome',builder:(_,__)=>const WelcomeScreen()),GoRoute(path:'/login',builder:(_,__)=>const LoginScreen()),GoRoute(path:'/onboarding',builder:(_,__)=>const OnboardingScreen()),StatefulShellRoute.indexedStack(builder:(_,__,shell)=>MainShell(navigationShell:shell),branches:[StatefulShellBranch(routes:[GoRoute(path:'/today',builder:(_,__)=>const TodayScreen())]),StatefulShellBranch(routes:[GoRoute(path:'/plan',builder:(_,__)=>const PlanScreen())]),StatefulShellBranch(routes:[GoRoute(path:'/debts',builder:(_,__)=>const DebtsScreen())]),StatefulShellBranch(routes:[GoRoute(path:'/transactions',builder:(_,__)=>const TransactionsScreen())]),StatefulShellBranch(routes:[GoRoute(path:'/profile',builder:(_,__)=>const ProfileScreen())])])]);});
class WelcomeScreen extends ConsumerStatefulWidget{const WelcomeScreen({super.key});@override ConsumerState<WelcomeScreen> createState()=>_WelcomeState();}
class _WelcomeState extends ConsumerState<WelcomeScreen>{bool busy=false;String? error;Future<void> demo()async{setState((){busy=true;error=null;});try{await ref.read(authControllerProvider.notifier).demoLogin();if(mounted)context.go('/today');}catch(e){if(mounted)setState(()=>error='Не удалось войти в демо: $e');}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Padding(padding:const EdgeInsets.all(28),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Spacer(),Text('ВЫХОД',style:Theme.of(c).textTheme.displayLarge),const Text('Не просто считай расходы. Найди путь наружу.'),const Spacer(),FilledButton(onPressed:busy?null:()=>c.go('/login'),child:const Text('Начать')),TextButton(onPressed:busy?null:demo,child:const Text('Посмотреть демо')),if(error!=null)Text(error!,style:TextStyle(color:Theme.of(c).colorScheme.error))]))));}
